def _numbered_choice_label(choice: object) -> str:
    """Label shown for a choice in a numbered prompt menu."""
    if isinstance(choice, enum.Enum):
        return choice.name

    return str(choice)


def _layout_numbered_menu(labels: cabc.Sequence[str], width: int) -> list[str]:
    """Lay out the numbered menu entries column by column, using the fewest
    rows that keep every line within ``width``. Falls back to a single
    column when nothing fits.
    """
    count = len(labels)
    number_width = len(str(count))
    entries = [
        f"{index:>{number_width}}) {label}" for index, label in enumerate(labels, 1)
    ]
    lengths = [term_len(entry) for entry in entries]

    def column_widths(rows: int) -> list[int]:
        return [max(lengths[start : start + rows]) for start in range(0, count, rows)]

    rows = count

    for candidate in range(1, count + 1):
        widths = column_widths(candidate)
        line_width = (
            len(_MENU_INDENT) + sum(widths) + len(_MENU_GAP) * (len(widths) - 1)
        )

        if line_width <= width:
            rows = candidate
            break

    widths = column_widths(rows)
    lines = []

    for row in range(rows):
        indices = list(range(row, count, rows))
        cells = []

        for position, index in enumerate(indices):
            cell = entries[index]

            if position < len(indices) - 1:
                cell += " " * (widths[index // rows] - lengths[index])

            cells.append(cell)

        lines.append(_MENU_INDENT + _MENU_GAP.join(cells))

    return lines


def _match_choice_number(value: object, choices: cabc.Sequence[t.Any]) -> int | None:
    """Return the 1-based menu number matching ``value``, or ``None``."""
    for number, choice in enumerate(choices, 1):
        if value == choice:
            return number

        if isinstance(value, str) and value == _numbered_choice_label(choice):
            return number

    return None


def _as_selection(value: t.Any) -> tuple[t.Any, ...]:
    """Normalize a multiple-mode default to a tuple."""
    if isinstance(value, (str, bytes)) or not isinstance(value, cabc.Iterable):
        return (value,)

    return tuple(value)


def _compress_numbers(numbers: cabc.Iterable[int]) -> str:
    """Render menu numbers as sorted runs: ``a-b`` for three or more
    consecutive numbers, the plain numbers otherwise.
    """
    ordered = sorted(set(numbers))
    pieces: list[str] = []
    start = 0

    while start < len(ordered):
        end = start

        while end + 1 < len(ordered) and ordered[end + 1] == ordered[end] + 1:
            end += 1

        run = ordered[start : end + 1]

        if len(run) >= 3:
            pieces.append(f"{run[0]}-{run[-1]}")
        else:
            pieces.extend(str(number) for number in run)

        start = end + 1

    return ",".join(pieces)


def _numbered_multiple_preview(
    default: t.Any, choices: cabc.Sequence[t.Any]
) -> str | None:
    selection = _as_selection(default)

    if not selection:
        return None

    numbers = []

    for item in selection:
        number = _match_choice_number(item, choices)

        if number is None:
            return None

        numbers.append(number)

    return _compress_numbers(numbers)


def _invalid_selection_message(shown: str, count: int) -> str:
    return _(
        "{selection} is not a valid selection. Enter a number from 1 to {count}."
    ).format(selection=shown, count=count)


def _parse_numbered_selection(
    text: str,
    choices: cabc.Sequence[t.Any],
    choice_type: Choice[t.Any],
    ctx: t.Any,
    hide_input: bool,
) -> tuple[tuple[t.Any, ...] | None, str | None]:
    """Parse a multiple-mode answer. Returns the selected choices in menu
    order, or an error message about the leftmost invalid piece.
    """
    count = len(choices)
    pieces = [piece.strip() for piece in text.split(",")]
    pieces = [piece for piece in pieces if piece]

    if not pieces:
        return None, _("Enter at least one number or name.")

    selected: set[int] = set()

    for piece in pieces:
        shown = _HIDDEN_INPUT_MASK if hide_input else f"'{piece}'"

        if _NUMBERED_INPUT_RE.fullmatch(piece):
            number = int(piece)

            if not 1 <= number <= count:
                return None, _invalid_selection_message(shown, count)

            selected.add(number)
            continue

        match = _NUMBERED_RANGE_RE.fullmatch(piece)

        if match is not None:
            start, end = int(match.group(1)), int(match.group(2))

            if not (1 <= start <= count and 1 <= end <= count):
                return None, _invalid_selection_message(shown, count)

            if start > end:
                return None, _(
                    "{piece} is not a valid range. The start must not be"
                    " greater than the end."
                ).format(piece=shown)

            selected.update(range(start, end + 1))
            continue

        try:
            converted = choice_type.convert(piece, None, ctx)
        except UsageError as e:
            message = _mask_hidden_input(e.message, piece) if hide_input else e.message
            return None, message

        for number, choice in enumerate(choices, 1):
            if choice is converted:
                selected.add(number)
                break
        else:
            selected.add(list(choices).index(converted) + 1)

    return tuple(choices[number - 1] for number in sorted(selected)), None


